    void shout(){
        System.out.println("动物发出叫声");
    }
}

class Dog extends Animal{   //Dog是Animal的子类
    public void shout(){
        super.shout();   //调用父类Animal的shout()方法
        System.out.println("汪汪汪……");
    }
