class Student {
    private String id;
    private String name;
    private int age;
    public Student(String id, String name, int age) { this.id = id; this.name = name; this.age = age; }
    public String toString() { return "[" + id + "," + name + "," + age + "]"; }
}

public class Main {
	public static void main(String args[]) {
       List<Student> list = new ArrayList<Student>();
       list.add(new Student("2016001","rose",18));
       list.add(new Student("2016002","hunifu",19));
       list.add(new Student("2016003","britsh",20));     
