import java.util.Scanner;

class House implements Comparable<House>{
  private String address;
  private double area;
  private double price;

  public House(String address, double area, double price) {
    setAddress(address);
    setArea(area);
    setPrice(price);
  }

  public String getAddress() {
    return address;
  }

  public void setAddress(String address) {
   this.address = address;
  }

  public double getArea() {
    return area;
  }

  public void setArea(double area) {
    if(area > 0)
      this.area = area;
    else
      throw new IllegalArgumentException("住宅的面积必须大于0");
  }

  public double getPrice() {
    return price;
  }

  public void setPrice(double price) {
    if(price > 0)
      this.price = price;
    else
      throw new IllegalArgumentException("住宅的价格必须大于0");
  }

  public int compareTo(House o) {
    if (price / area > o.price / o.area)
      return 1;
    else if (price / area < o.price / o.area)
      return -1;
    else
      return 0;
  }

  @Override
  public String toString() {
    return "House{address=" + address + ", area=" + area + ", price=" + price + "}";
  }
}

public class Main {
  public static void main(String[] args) {
    Scanner input = new Scanner(System.in);
    for(int i=0; i<10; i++) {
    try {
        House house1 = new House(input.next(), input.nextDouble(), input.nextDouble());
        House house2 = new House(input.next(), input.nextDouble(), input.nextDouble());
        House maxHouse;
        if (house1.compareTo(house2) >= 0)
          maxHouse = house1;
        else
          maxHouse = house2;
        System.out.println("The max of " + house1 + " and " + house2 + " is " + maxHouse);
      } catch (IllegalArgumentException e1) {
        System.out.println(e1.getMessage());
	    input.nextLine();
      } catch (Exception e2) {
        System.out.println(e2.getMessage());
        input.nextLine();
      }
    }
  }
}

