import java.util.*;
//线程类：计算整数序列和
class SumList implements Runnable {
	private ArrayList lt=null;//存放整数序列的列表	
	SumList(ArrayList lt){
		this.lt=lt;
	}
	//线程体
	public void run() {
		int sum=0;
		for (int i = 0; i < lt.size(); i++)
			sum += (Integer) lt.get(i);//取出序列元素累加
		System.out.println(sum);
	}
}
//测试类
public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);		
		int n=sc.nextInt();//输入序列个数
		int m=sc.nextInt();//输入每个序列中的整数个数
		for (int i = 0; i < n; i++) {			
			ArrayList<Integer> score = new ArrayList<Integer>();//创建求和列表对象	
			for (int j = 0; j < m; j++) {
				score.add(sc.nextInt());
			}
			SumList sl = new SumList(score);
			Thread th=new Thread(sl);//创建线程对象			
			th.start();
            try { th.join(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); return; }//启动线程
		}
		sc.close();
	}
}

