import java.util.*;

class Factorial implements Runnable { // 声明线程类
	private int n;
	private long factorial;

	Factorial(int n) {
		this.n = n;
	}

	// 返回阶乘
	public long getFactorial() {
		return factorial;
	}

	// 线程体
	@Override

	public void run() { // 线程类必须实现接口定义的方法
		factorial = 1;
		for (int i = 2; i <= n; i++)
			factorial *= i;
	}
}

