import java.util.Scanner;

abstract class Vehicle { public abstract int rent(); }
class Truck extends Vehicle {
    private int load;
    public Truck(int load) { this.load = load; }
    public int rent() { return 1000 * load; }
}
class Car extends Vehicle {
    private int level;
    public Car(int level) { this.level = level; }
    public int rent() { return 200 * level; }
}
class CarRentCompany {
    public static int rentVehicles(Vehicle[] vehicles) {
        int total = 0;
        for (Vehicle vehicle : vehicles) total += vehicle.rent();
        return total;
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        CarRentCompany company = new CarRentCompany();
        Vehicle[] vehicles = new Vehicle[sc.nextInt()];
        for (int i = 0; i < vehicles.length; i++) {
            int type = sc.nextInt(), value = sc.nextInt();
            vehicles[i] = type == 1 ? new Truck(value) : new Car(value);
        }
        System.out.println(CarRentCompany.rentVehicles(vehicles));
        sc.close();
    }
}

