import java.util.ArrayList;
import java.util.Scanner;

class Person {
    private String name;
    private int age;
    public Person(String name, int age) { this.name = name; this.age = age; }
    @Override
    public boolean equals(Object other) {
        if (this == other) return true;
        if (!(other instanceof Person)) return false;
        Person person = (Person) other;
        return age == person.age && (name == null ? person.name == null : name.equalsIgnoreCase(person.name));
    }
    @Override
    public int hashCode() {
        // 相等对象年龄必相等，按年龄散列满足契约；允许不同姓名出现散列冲突。
        return Integer.hashCode(age);
    }
    @Override
    public String toString() { return "Person [name=" + name + ", age=" + age + "]"; }
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        ArrayList<Person> people = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            Person person = new Person(name.equals("null") ? null : name, sc.nextInt());
            if (!people.contains(person)) people.add(person);
        }
        System.out.println(people);
        sc.close();
    }
}

